using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "MoonBathCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Moonie/MoonBathCustomDescription", order = 0)]
public class MoonBathCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		MoonBathAction moonBathAction = battleAction as MoonBathAction;
		string actionDescription = moonBathAction.PurifyAction.GetActionDescription(GetAmountWithoutEquation(amountModified), GetBonusAmountWithoutEquation(amountModified));
		return Smart.Format(GetRawLocalizedDescription(battleAction), Smart.Format(base.localizationManager.GetLocalizedIfYouDo(), actionDescription.LowercaseFirst()), moonBathAction.TagHexDie.GetTagName(), GetAmountWithUnlockablesModification(amountModified), moonBathAction.ParalyzedHexDieAdditionalTimes);
	}
}
